custom_css:
@import url('/css/tavernnext-atelier.css');

:root {
    --tn-accent: #658b70;
    --tn-accent-hover: #557a60;
    --tn-accent-soft: rgba(111, 157, 124, 0.18);
    --tn-accent-fill: #c7dfcc;
    --tn-accent-fill-hover: #b8d4bf;
    --tn-accent-contrast: #213126;
    --tn-accent-border: #aecbb5;
    --tn-accent-highlight: rgba(255, 255, 255, 0.7);
    --tn-accent-shadow: rgba(74, 111, 84, 0.2);
    --tn-status-contrast: #ffffff;
    --tn-surface-0: rgba(246, 247, 245, 0.96);
    --tn-surface-1: rgba(255, 255, 255, 0.96);
    --tn-surface-2: rgba(237, 239, 236, 0.96);
    --tn-surface-solid: #ffffff;
    --tn-field: rgba(246, 247, 245, 0.96);
    --tn-field-hover: #ffffff;
    --tn-field-highlight: rgba(255, 255, 255, 0.9);
    --tn-hover: rgba(111, 157, 124, 0.12);
    --tn-active: rgba(111, 157, 124, 0.2);
    --tn-selected: rgba(111, 157, 124, 0.16);
    --tn-hairline: rgba(58, 63, 59, 0.13);
    --tn-code-bg: #eceeeb;
    --tn-code-text: #343834;
    --tn-danger: #b52d45;
    --tn-success: #517d5d;
    --tn-warning: #956521;
    --tn-scrollbar: rgba(58, 63, 59, 0.28);
    --tn-shadow-sm: 0 1px 2px rgba(24, 27, 24, 0.05), 0 5px 18px rgba(24, 27, 24, 0.06);
    --tn-shadow-lg: 0 14px 36px rgba(24, 27, 24, 0.13);
}

body { color-scheme: light !important; }
